//! IAU body orientation vs CSPICE `tisbod` (fixture: tests/fixtures/iau_rotation_spice.csv,
//! generated by tools/fixtures/gen_iau_rotation_spice.py from the same pck00011.tpc).

use sim_core::bodies::BodyId;
use sim_core::math::V3;
use sim_core::orientation::iau_body_orientation;
use sim_core::time::Epoch;

#[test]
fn rotation_matrices_and_rates_match_spice() {
    let (mut worst_angle, mut worst_w) = (0.0f64, 0.0f64);
    let mut n = 0;
    for line in include_str!("fixtures/iau_rotation_spice.csv")
        .lines()
        .skip(1)
    {
        let f: Vec<f64> = line.split(',').map(|x| x.parse().unwrap()).collect();
        let body = BodyId(f[0] as i32);
        let o = iau_body_orientation(body, Epoch::from_tdb_seconds(f[1])).expect("model");
        // Rotation error angle from the largest element difference (small-angle).
        let mut max_diff = 0.0f64;
        for i in 0..3 {
            let row = [
                o.icrf_to_bf.rows[i].x,
                o.icrf_to_bf.rows[i].y,
                o.icrf_to_bf.rows[i].z,
            ];
            for j in 0..3 {
                max_diff = max_diff.max((row[j] - f[2 + 3 * i + j]).abs());
            }
        }
        let w_spice = V3::new(f[11], f[12], f[13]);
        let dw = (o.omega_bf - w_spice).norm() / w_spice.norm();
        // W reaches ~3e7 degrees at ±100 years (Jupiter: 870.5°/day × 36,000 days).
        // At that magnitude one f64 ulp is ~4e-9° ≈ 7e-11 rad, and the rounding differs
        // between our order of operations and SPICE's. 2e-10 rad is < 1.5 cm at
        // Jupiter's 1-bar radius and less elsewhere.
        assert!(
            max_diff < 2e-10,
            "body {} at {}: rotation differs by {max_diff:e}",
            body.0,
            f[1]
        );
        assert!(dw < 1e-9, "body {} at {}: |Δω|/|ω| = {dw:e}", body.0, f[1]);
        worst_angle = worst_angle.max(max_diff);
        worst_w = worst_w.max(dw);
        n += 1;
    }
    assert_eq!(n, 135);
    eprintln!("worst rotation element diff {worst_angle:.2e}, worst relative ω diff {worst_w:.2e}");
}
